    data.frame(method = part$method[1L], usable = nrow(part),
               bias = mean(part$estimate) - truth,
               empirical_sd = stats::sd(part$estimate),
               mean_standard_error = mean(part$standard_error),
               coverage = mean(part$covered))
  }))
}

