gen <- lta(course_engagement, vars, "student", n_profiles = 2, time = "sequence",
           transition_covariates = "previous_grade", n_starts = 2, seed = 1)
cat(class(hom)[1], class(gen)[1], "\n")
probe(hom, class(hom)[1]); probe(gen, class(gen)[1])

